        // the name everywhere else.
        assert_eq!(typed_as_directory(Path::new("dir\\")), cfg!(windows));
        assert_eq!(
            source_path_to_posix(Path::new("dir\\")),
            if cfg!(windows) { "dir/" } else { "dir\\" }
        );
    }

