    fn a_failure_past_the_cap_is_saved_by_its_own_bytes() {
        let dir = tempfile::tempdir().unwrap();
        let store = RunStore::new(dir.path());
        let run_id = job_log::new_run_id().unwrap();
        let spec = JobSpec::new(
            "m1",
