            "/".into(),
            SpecEndpoint::Local { path: "/a/".into() },
            SpecEndpoint::Local { path: "/b/".into() },
            SpecOptions::default(),
            None,
        );
        let record = RunRecord::starting(&run_id, &spec);
        }
    }
