    fn linked_unknown_allows_ordinary_retry() {
        let long = format!("{}file", "abc/".repeat(1125));
        let mut outcome = SinkOutcome::failed_unknown(long, "cannot inspect");
        outcome.record_failure("ordinary", "missing");
        let (failed_paths, failed_paths_raw, failed_paths_truncated) = outcome.wire_failed_identities();
        let failures = outcome.wire_failures_linked(&failed_paths, &failed_paths_raw);
        assert_eq!(failures[0].failed_path_at, 1);
        let (left_in_place, left_in_place_raw, left_in_place_truncated) = outcome.wire_left_account(&failures);
        let s = TransferSummary { files_failed: 2, failed_paths, failed_paths_raw, failed_paths_truncated,
            failures, left_in_place, left_in_place_raw, left_in_place_truncated, ..Default::default() };
        let next = PassFailures::from_summary(&s).pass_set(true).0;
        assert!(next.text.contains(&PathBuf::from("ordinary")), "eligible {:?}", next.text);
    }

    #[test]
    fn known_withheld_name_survives_clean_sibling() {
        let main = PassFailures {
            files_failed: 2, failed_paths: vec!["unseen".into(), "ordinary".into()],
            failed_paths_raw: vec![vec![], vec![]],
            failures: vec![FileFailure { relative_path:"unseen".into(), reason:"cannot inspect".into(), left_unknown:true, ..Default::default() }],
            ..Default::default()
        };
        let (eligible, _, short) = main.pass_set(true);
        assert_eq!(eligible.len(), 1);
        let final_state = main.after_pass(eligible.len(), short, PassFailures::default());
        let mut summary = TransferSummary::default();
        final_state.apply_to_summary(&mut summary);
        assert_eq!(summary.files_failed, 1);
        assert!(summary.failed_paths.contains(&"unseen".to_owned()), "final paths {:?}, unretried {}", summary.failed_paths, final_state.unretried);
    }
}

