#[cfg(test)]
mod review_probe {
    use super::*;
    use blit_core::remote::transfer::sink::SinkOutcome;

    #[test]
    fn saved_unknown_job() {
        let tmp = tempfile::tempdir().unwrap();
        let dir = tmp.path();
        let src = dir.join("source");
        let dst = dir.join("destination");
        let cfg = dir.join("config");
        for path in [&src, &dst, &cfg] { std::fs::create_dir(path).unwrap(); }
        std::fs::write(src.join("file"), b"complete").unwrap();
        std::fs::write(dst.join("file"), b"partial__").unwrap();
        let id = job_log::new_run_id().unwrap();
        let spec = JobSpec::new(&job_log::machine_id(&cfg).unwrap(), "copy",
            dir.to_string_lossy().into_owned(),
            SpecEndpoint::Local {path:format!("{}/", src.display())}, SpecEndpoint::Local {path:format!("{}/", dst.display())},
            SpecOptions { ignore_existing: true, ..Default::default() }, None);
        let store = RunStore::new(runs_dir(&cfg));
        let record = RunRecord::starting(&id, &spec);
        let live = store.begin(&spec, &record).unwrap();
        let recorded = Recorded { store: store.clone(), spec, record, keep:50, _live:live };
        let outcome = SinkOutcome::failed_unknown("file", "cannot inspect at close");
        let (failed_paths, failed_paths_raw, failed_paths_truncated) = outcome.wire_failed_identities();
        let failures = outcome.wire_failures_linked(&failed_paths, &failed_paths_raw);
        let (left_in_place, left_in_place_raw, left_in_place_truncated) = outcome.wire_left_account(&failures);
        let summary = blit_core::generated::TransferSummary { files_failed:1, failed_paths, failed_paths_raw,
            failed_paths_truncated, failures, left_in_place, left_in_place_raw, left_in_place_truncated, ..Default::default() };
        let totals = RunTotals::from(&summary);
        assert_eq!(totals.failed_files()[0].left_in_place, None);
        finish_record(recorded, None, Outcome::Failed, None, Some(totals), &Default::default(), false, Some(false));
        let result = std::process::Command::new(std::env::var_os("REVIEW_CLI_BIN").unwrap())
            .arg("--config-dir").arg(cfg).arg("jobs").arg("retry").arg(&id).output().unwrap();
        assert_eq!(std::fs::read(dst.join("file")).unwrap(), b"partial__");
        assert!(!result.status.success(), "jobs retry exited {:?} with the partial still present", result.status.code());
    }
}

