#[cfg(test)]
mod review_probe {
    use super::*;
    use blit_core::job_log::{EventBody, Outcome, Role, RunInfo};
    use blit_core::run_log::LogPlace;

    #[test]
    fn overcount_after_reading_log() {
        let temp = tempfile::tempdir().unwrap();
        let spec = JobSpec::new("m1", "copy", "/".into(),
            blit_core::job_record::SpecEndpoint::Local { path:"/s/".into() },
            blit_core::job_record::SpecEndpoint::Local { path:"/d/".into() },
            Default::default(), None);
        let mut record = RunRecord::starting("19191919191919191919191919191919", &spec);
        record.files_failed = 1;
        record.failures_truncated = true;
        let whole = format!("{}leaf", "dir/".repeat(1125));
        record.failures = vec![blit_core::job_record::Failure{path:whole.clone(), reason:"missing".into(), raw:None}];
        let place = LogPlace { dir:temp.path().join("jobs/logs"),participant:"m1".into(), keep:50, finished:None };
        let writer = place.start(&record.run_id, 1, Role::Initiator, RunInfo::default()).unwrap();
        for p in [whole, "[truncated]…leaf".into()] {
            writer.record(EventBody::FileFailed {path:p, reason:"missing".into(), raw:None, left_in_place:Some(false)});
        }
        assert!(writer.finish(Outcome::Failed,None).complete);
        if let Ok((names,_)) = failed_identities(temp.path(), &record) {
            panic!("selected {} names for one failed file", names.len());
        }
    }
}

