#[cfg(test)]
mod review_encoding_probe {
    use super::*;
    use blit_core::remote::transfer::sink::{failures_from_report, failures_to_report};
    #[test]
    fn an_unlinked_diagnostic_stays_unlinked_when_its_display_matches_a_name() {
        let original = FileFailure { relative_path:format!("{}name", "sub/".repeat(1126)), reason:"long file's reason".into(), left_unknown:true, ..Default::default() };
        let shortened = FileFailure::from_wire(&original.to_wire());
        assert!(shortened.path_shortened);
        let distinct_exact_name = shortened.relative_path.clone();
        let names = vec![distinct_exact_name];
        let encoded = failures_to_report(&[shortened], &names, &[]);
        let decoded = failures_from_report(&encoded, &names, &[]);
        assert!(decoded[0].path_shortened && encoded[0].failed_path_at == 0,
            "shortened = {}, index = {}", decoded[0].path_shortened, encoded[0].failed_path_at);
    }
}
